/** v5 gemv (lops.js gemv's arguments); opts = { ND, L, mode, deq } */
export function gemvV5(g, a, opts = {}) {
  const o = v5opts(g, a, opts), K = a.K, N = a.N, woff = a.w.off || 0;
  const kch = !a.kPer && K > KCH ? Math.ceil(K / 256) * 256 : KCH; if (kch > 3072) throw new Error('kernx v5: K ' + K + ' needs a kPer');
  const kPer = Math.min(kch, a.kPer || K); if (kPer % 32) throw new Error('kernx v5: kPer must be a multiple of 32');
  const xch = Math.min(kch, Math.ceil(kPer / 64) * 64);   // a small K stages (and zero-fills) only what it reads
  const cfg = { M: 1, ND: o.ND, L: o.L, mode: o.mode, deq: o.deq, xch, pro: o.pro, epi: o.epi, one: true };
  fitV5(g, cfg); const pipe = g.pipeline(`kx.gemv.v5.${o.pro}.${o.epi}.${o.mode === 'direct' ? 0 : xch}.${o.tag}`, () => codeV5(cfg));
  const nsplit = Math.ceil(K / kPer); if (o.epi !== 'store' && nsplit > 1) throw new Error('kernx v5: ' + o.epi + ' needs one split');
  if (N % 64) throw new Error('kernx v5: N % 64');
  const wG = a.w.cols / 32, mx = a.epi === 'softcap' ? a.mx.buf : a.stat ? a.stat.buf : dummy(g, 3);
  const tileB = wG * 1280, NT = N / 64, lim = (g.limits && g.limits.maxStorageBufferBindingSize) || Infinity;
  const pr = (wo, t0) => P().u32(N).u32(K).u32(wG).u32(kPer).u32(nsplit).u32(a.ldy || N).u32(wo / 4).u32(a.norm ? a.norm.off || 0 : 0)
    .u32(a.stat ? a.stat.off || 0 : 0).u32(a.x.rowB || 0).u32(a.ev ? a.ev.off || 0 : 0).f32(a.cap || 30).u32(a.src ? a.src.ld : 0).u32(a.src ? a.src.n : 0).u32(t0).u32(0);
  const nwb = a.norm ? a.norm.buf : dummy(g, 0), rest = [bw(a.y.buf), bw(nwb), bw(a.ev ? a.ev.buf : dummy(g, 1)), bw(mx)];
  const xtra = o.mode === 'direct' ? [bw16(a.x.buf), bw16(nwb)] : [];
  if (NT * tileB + woff % 256 <= lim || o.epi === 'geglu') {
    g.runner.dispatch(pipe, [bw(a.x.buf), bw(a.w.buf), ...rest, bw16(a.w.buf), ...xtra], pr(woff, 0).ab, [NT, nsplit], (N * K * 0.625) / g.rate.mem + 2e-5);
    return nsplit;
  }
  let per = Math.max(1, Math.floor((lim - 256) / tileB)); while (per > 1 && (per * tileB) % 256) per--;
  for (let t0 = 0; t0 < NT; t0 += per) {
    const nt = Math.min(per, NT - t0), { start, base, wv } = tileWin(a, t0, nt, tileB);
    g.runner.dispatch(pipe, [bw(a.x.buf), wv, ...rest, wv, ...xtra], pr(start - base, t0).ab, [nt, nsplit], (nt * 64 * K * 0.625) / g.rate.mem + 2e-5);
  }
  return nsplit;
}

/** v5 gemvM (lops_spec.js gemvM's arguments); opts = { ND, L, mode, deq, XB (staged: x floats per sub-chunk, all x rows) } */
export function gemvMV5(g, a, opts = {}) {
  const o = v5opts(g, a, opts), M = a.M, K = a.K, N = a.N, woff = a.w.off || 0, XB = opts.XB || 4096;
  const kPer = a.kPer ? Math.min(KCH, a.kPer) : K; if (kPer % 32) throw new Error('kernx v5: kPer must be a multiple of 32');
  const xch = Math.min(Math.ceil(kPer / 64) * 64, M <= 1 ? KCH : Math.max(64, Math.min(KCH, Math.floor(XB / M / 64) * 64)));
  const cfg = { M, ND: o.ND, L: o.L, mode: o.mode, deq: o.deq, xch, pro: o.pro, epi: o.epi, one: false };
  fitV5(g, cfg); const pipe = g.pipeline(`kx.gemvM.v5.${o.pro}.${o.epi}.${M}.${o.mode === 'direct' ? 0 : xch}.${o.tag}`, () => codeV5(cfg));
  const nsplit = Math.ceil(K / kPer); if (o.epi !== 'store' && nsplit > 1) throw new Error('kernx v5: ' + o.epi + ' needs one split');
  if (N % 64) throw new Error('kernx v5: N % 64');
  const wG = a.w.cols / 32, tileB = wG * 1280, NT = N / 64, lim = (g.limits && g.limits.maxStorageBufferBindingSize) || Infinity;
  const ldm = a.y.ldm || N, ldy = a.y.ldy || M * ldm;
  const pr = (wo, t0) => P().u32(N).u32(K).u32(wG).u32(kPer).u32(ldy).u32(ldm).u32(a.x.ldx || K).u32(wo / 4).u32(a.norm ? a.norm.off || 0 : 0)
    .u32(a.stat ? a.stat.off || 0 : 0).u32(a.stat ? a.stat.ld || 2 : 0).u32(a.x.rowB || 0).u32(a.ev ? a.ev.off || 0 : 0).u32(a.ev ? a.ev.ld || 0 : 0)
    .f32(a.cap || 30).u32(a.src ? a.src.n : 1).u32(a.src ? a.src.ld : 0).u32(t0).u32(NT).u32(0);
  const nwb = a.norm ? a.norm.buf : dummy(g, 0);
  const rest = [bw(a.y.buf), bw(nwb), bw(a.ev ? a.ev.buf : dummy(g, 1)), bw(a.stat ? a.stat.buf : dummy(g, 2)), bw(a.mx ? a.mx.buf : dummy(g, 3))];
  const xtra = o.mode === 'direct' ? [bw16(a.x.buf), bw16(nwb)] : [];
  const sec = (M * N * K * 0.625) / (g.rate.mem * 4) + 2e-5;
  if (NT * tileB + woff % 256 <= lim || o.epi === 'geglu') {
    g.runner.dispatch(pipe, [bw(a.x.buf), bw(a.w.buf), ...rest, bw16(a.w.buf), ...xtra], pr(woff, 0).ab, [NT, nsplit], sec);
    return nsplit;
  }
  let per = Math.max(1, Math.floor((lim - 256) / tileB)); while (per > 1 && (per * tileB) % 256) per--;
  for (let t0 = 0; t0 < NT; t0 += per) {
    const nt = Math.min(per, NT - t0), { start, base, wv } = tileWin(a, t0, nt, tileB);
    g.runner.dispatch(pipe, [bw(a.x.buf), wv, ...rest, wv, ...xtra], pr(start - base, t0).ab, [nt, nsplit], sec * nt / NT);
  }
  return nsplit;
}

/** for the harness: the generated WGSL of a variant (to read or to log a compile error with) */
export function v5code(cfg) { return codeV5(Object.assign({ M: 1, ND: 4, L: 8, mode: 'stage', deq: 'shift', xch: KCH, pro: 'raw', epi: 'store', one: true }, cfg)); }

// ================================================================================================================ which kernel a call takes
/** the phone's picks (bench v041): prologue.epilogue.NxK -> v5 options; a shape not listed keeps the engine's own kernel */
export const PICK = {"rms.softcap.262144x1536": {"ND": 4, "L": 16, "deq": "mask"}, "rms.geglu.6144x1536": {"ND": 2, "L": 8}, "raw.store.1536x6144": {"ND": 4, "L": 16, "mode": "direct"}, "rms.geglu.12288x1536": {"ND": 2, "L": 8}, "raw.store.1536x12288": {"ND": 4, "L": 16, "mode": "direct"}, "raw.store.8960x1536": {"ND": 4, "L": 16, "mode": "direct"}, "rms.store.3072x2560": {"ND": 2, "L": 8}, "raw.store.2560x2048": {"ND": 2, "L": 8}, "rms.store.6144x2560": {"ND": 2, "L": 8}, "raw.store.2560x4096": {"ND": 4, "L": 16, "mode": "direct"}, "rms.store.2048x2560": {"ND": 2, "L": 8}, "rms.store.4096x2560": {"ND": 2, "L": 8}, "rms.softcap.262144x2560": {"ND": 4, "L": 16, "deq": "mask"}, "rms.geglu.10240x2560": {"ND": 2, "L": 8}, "raw.store.2560x10240": {"ND": 4, "L": 16, "mode": "direct"}, "raw.store.256x2560": {"ND": 4, "L": 16, "mode": "direct", "deq": "u8"}, "raw.store.10752x2560": {"ND": 4, "L": 8}};
export const KX = { on: true };
export function setKX(on) { KX.on = !!on; }
/** the v5 options for a call (null = the engine's own) */
export function kxPick(a) {
  if (!KX.on || !okV5(a)) return null;
  return PICK[`${a.pro || 'raw'}.${a.epi || 'store'}.${a.N}x${a.K}`] || null;
}
